import { Hono } from 'hono';
import { audit, Env, fail, fallbackOwner, hashPassword, isAdmin, normalizeCode, now, randomToken, roleAllowed, today, uid, UserRow, verifyPassword } from './final/core';
import { ensureFinalSchema, subjectOptions } from './final/schema';

type Vars = { user: UserRow };
const app = new Hono<{ Bindings: Env; Variables: Vars }>();
let schemaPromise: Promise<void> | null = null;
const ensure = (db: D1Database) => (schemaPromise ||= ensureFinalSchema(db).catch((e) => { schemaPromise = null; throw e; }));

app.use('/api/*', async (c, next) => {
  if (!c.env.DB) return fail(c, 'D1 veritabanı bağlı değil.', 503);
  try { await ensure(c.env.DB); } catch (e) { console.error('schema upgrade', e); return fail(c, 'Veritabanı hazırlanamadı.', 500, String(e)); }
  if (['POST','PUT','PATCH','DELETE'].includes(c.req.method)) {
    const origin = c.req.header('Origin');
    if (origin) {
      try { if (new URL(origin).host !== new URL(c.req.url).host) return fail(c, 'Geçersiz istek kaynağı.', 403); }
      catch { return fail(c, 'Geçersiz istek kaynağı.', 403); }
    }
  }
  if (['/api/health','/api/setup/status','/api/auth/login'].includes(c.req.path)) return next();
  const bearer = c.req.header('Authorization')?.replace(/^Bearer\s+/i, '').trim();
  const cookie = c.req.header('Cookie')?.split(';').map(x => x.trim()).find(x => x.startsWith('yd_session='))?.slice('yd_session='.length);
  const token = bearer || cookie;
  if (!token) return fail(c, 'Oturum gerekli.', 401);
  const user = await c.env.DB.prepare(`SELECT u.* FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token=? AND s.expires_at>datetime('now') AND u.status='ACTIVE' AND u.deleted_at IS NULL`).bind(token).first<UserRow>();
  if (!user) return fail(c, 'Oturum süresi dolmuş.', 401);
  c.set('user', user);
  return next();
});

const requireRoles = (...roles: string[]) => async (c: any, next: () => Promise<void>) => {
  const u = c.get('user') as UserRow;
  if (!roleAllowed(u, roles)) return fail(c, 'Bu işlem için yetkiniz yok.', 403);
  await next();
};

async function institutionAllowed(db: D1Database, user: UserRow, institutionId: string) {
  if (user.role === 'KURUM') return user.institution_id === institutionId;
  if (user.role === 'PERSONEL') return !!(await db.prepare(`SELECT id FROM institutions WHERE id=? AND staff_id=? AND deleted_at IS NULL`).bind(institutionId, user.id).first());
  return true;
}

async function upsertInstitutionPortalUser(db: D1Database, institution: { id: string; name: string; code: string }, password?: string) {
  if (!password) return;
  if (password.length < 8) throw new Error('Kurum şifresi en az 8 karakter olmalı.');
  const loginCode = normalizeCode(institution.code);
  const existing = await db.prepare(`SELECT id FROM users WHERE institution_id=? AND role='KURUM' AND deleted_at IS NULL ORDER BY created_at LIMIT 1`).bind(institution.id).first<{ id: string }>();
  const hash = await hashPassword(password);
  if (existing) {
    await db.prepare(`UPDATE users SET login_code=?,password_hash=?,full_name=?,status='ACTIVE',must_change_password=0,updated_at=? WHERE id=?`).bind(loginCode,hash,`${institution.name} Kurum Hesabı`,now(),existing.id).run();
  } else {
    const email = `${loginCode.toLowerCase()}@kurum.yildizyayin.local`;
    await db.prepare(`INSERT INTO users(id,email,password_hash,full_name,role,status,institution_id,must_change_password,login_code,created_at,updated_at) VALUES(?,?,?,?, 'KURUM','ACTIVE',?,0,?,?,?)`)
      .bind(uid('user'),email,hash,`${institution.name} Kurum Hesabı`,institution.id,loginCode,now(),now()).run();
  }
}

app.get('/api/health', c => c.json({ ok: true, service: c.env.APP_NAME || 'Yıldız Deneme Platformu', database: true, time: now() }));
app.get('/api/setup/status', async c => {
  const r = await c.env.DB.prepare(`SELECT COUNT(*) count FROM users`).first<{ count: number }>();
  return c.json({ ok: true, database: true, ready: true, users: r?.count || 0, version: 'final-2026-08-19' });
});

app.post('/api/auth/login', async c => {
  const body: any = await c.req.json().catch(() => ({}));
  const identifier = String(body.identifier || body.email || '').trim();
  const password = String(body.password || '');
  if (!identifier || !password) return fail(c, 'E-posta / kurum kodu ve şifre gerekli.');
  const user = await c.env.DB.prepare(`SELECT * FROM users WHERE (lower(email)=lower(?) OR upper(login_code)=upper(?)) AND deleted_at IS NULL`).bind(identifier,normalizeCode(identifier)).first<UserRow & { password_hash: string }>();
  if (!user || !(await verifyPassword(password,user.password_hash))) return fail(c, 'Giriş bilgileri hatalı.', 401);
  if (user.status !== 'ACTIVE') return fail(c, 'Bu hesap pasif.', 403);
  const token = randomToken();
  const expires = new Date(Date.now() + 7 * 86400000).toISOString();
  await c.env.DB.prepare(`INSERT INTO sessions(id,user_id,token,expires_at,ip_address,user_agent,created_at) VALUES(?,?,?,?,?,?,?)`).bind(uid('sess'),user.id,token,expires,c.req.header('CF-Connecting-IP') || '',c.req.header('User-Agent') || '',now()).run();
  const secure = c.env.APP_ENV === 'production' ? '; Secure' : '';
  c.header('Set-Cookie',`yd_session=${token}; Path=/; HttpOnly; SameSite=Strict; Max-Age=604800${secure}`);
  const { password_hash: _ph, ...safe } = user as any;
  return c.json({ ok: true, user: safe, expires_at: expires });
});
app.get('/api/auth/me', c => c.json({ ok: true, user: c.get('user') }));
app.post('/api/auth/logout', async c => {
  const cookie = c.req.header('Cookie')?.split(';').map(x => x.trim()).find(x => x.startsWith('yd_session='))?.slice('yd_session='.length) || '';
  if (cookie) await c.env.DB.prepare(`DELETE FROM sessions WHERE token=?`).bind(cookie).run();
  c.header('Set-Cookie','yd_session=; Path=/; HttpOnly; SameSite=Strict; Max-Age=0');
  return c.json({ ok: true });
});
app.post('/api/auth/change-password', async c => {
  const u = c.get('user'); const b: any = await c.req.json().catch(() => ({}));
  if (!b.current_password || !b.new_password || String(b.new_password).length < 10) return fail(c,'Yeni şifre en az 10 karakter olmalı.');
  const row = await c.env.DB.prepare(`SELECT password_hash FROM users WHERE id=?`).bind(u.id).first<{password_hash:string}>();
  if (!row || !(await verifyPassword(String(b.current_password),row.password_hash))) return fail(c,'Mevcut şifre hatalı.',401);
  await c.env.DB.prepare(`UPDATE users SET password_hash=?,must_change_password=0,updated_at=? WHERE id=?`).bind(await hashPassword(String(b.new_password)),now(),u.id).run();
  await audit(c.env.DB,u,'PASSWORD_CHANGE','user',u.id); return c.json({ok:true});
});

app.get('/api/bootstrap', async c => {
  const u = c.get('user'); const db = c.env.DB;
  const [seasons,grades,publishers,staff] = await Promise.all([
    db.prepare(`SELECT * FROM seasons ORDER BY year_start DESC`).all(),
    db.prepare(`SELECT * FROM grade_levels WHERE is_active=1 ORDER BY sort_order`).all(),
    db.prepare(`SELECT * FROM publishers WHERE deleted_at IS NULL ORDER BY name`).all(),
    db.prepare(`SELECT id,full_name,email,role,status FROM users WHERE role IN ('SUPER_ADMIN','ADMIN','PERSONEL') AND status='ACTIVE' AND deleted_at IS NULL ORDER BY full_name`).all()
  ]);
  let instSql = `SELECT i.*,u.full_name staff_name,(SELECT group_concat(grade_level_id) FROM institution_grade_levels ig WHERE ig.institution_id=i.id) grade_ids FROM institutions i LEFT JOIN users u ON u.id=i.staff_id WHERE i.deleted_at IS NULL`;
  const vals:any[]=[];
  if (u.role === 'KURUM') { instSql += ` AND i.id=?`; vals.push(u.institution_id); }
  if (u.role === 'PERSONEL') { instSql += ` AND i.staff_id=?`; vals.push(u.id); }
  instSql += ` ORDER BY i.name`;
  const institutions = await db.prepare(instSql).bind(...vals).all<any>();
  return c.json({ ok:true,user:u,seasons:seasons.results,grades:grades.results,publishers:publishers.results,staff:staff.results,subjects:subjectOptions,institutions:(institutions.results||[]).map((x:any)=>({...x,grade_level_ids:x.grade_ids?String(x.grade_ids).split(','):[]})) });
});

app.get('/api/dashboard', async c => {
  const db=c.env.DB,u=c.get('user');
  const instWhere=u.role==='KURUM'?' AND o.institution_id=?':u.role==='PERSONEL'?' AND o.staff_id=?':''; const bind=u.role==='KURUM'?u.institution_id:u.role==='PERSONEL'?u.id:null;
  const one=async(sql:string,v?:any)=>v?db.prepare(sql).bind(v).first<any>():db.prepare(sql).first<any>();
  const orders=await one(`SELECT COUNT(*) total,COALESCE(SUM(quantity),0) quantity,COALESCE(SUM(total_price),0) revenue,SUM(CASE WHEN status NOT IN ('TESLIM_EDILDI','IPTAL') THEN 1 ELSE 0 END) pending FROM orders o WHERE 1=1${instWhere}`,bind);
  const pendingSql=`SELECT COUNT(*) count FROM institution_exam_plans p LEFT JOIN orders o ON o.institution_id=p.institution_id AND o.exam_id=p.exam_id AND o.status!='IPTAL' JOIN institutions i ON i.id=p.institution_id WHERE o.id IS NULL${u.role==='KURUM'?' AND p.institution_id=?':u.role==='PERSONEL'?' AND i.staff_id=?':''}`;
  const pending=await one(pendingSql,bind);
  const opportunities=await one(`SELECT COUNT(*) count FROM sales_opportunities so WHERE status NOT IN ('SIPARIS_VERDI','ILGILENMIYOR','BASKA_YAYINEVI_ALDI','KATILMAYACAK')${u.role==='PERSONEL'?' AND staff_id=?':''}`,u.role==='PERSONEL'?u.id:null);
  const delivery=await one(`SELECT COUNT(*) count FROM deliveries d JOIN orders o ON o.id=d.order_id WHERE d.status!='TESLIM_EDILDI'${u.role==='KURUM'?' AND o.institution_id=?':u.role==='PERSONEL'?' AND o.staff_id=?':''}`,bind);
  const upcoming=await one(`SELECT COUNT(*) count FROM exams WHERE is_active=1 AND deleted_at IS NULL AND application_start_date BETWEEN date('now') AND date('now','+30 day')`);
  const deadlines=await db.prepare(`SELECT e.id,e.name,e.last_order_date,e.exam_type,e.subject,g.name grade,p.name publisher FROM exams e JOIN grade_levels g ON g.id=e.grade_level_id JOIN publishers p ON p.id=e.publisher_id WHERE e.is_active=1 AND e.deleted_at IS NULL AND e.last_order_date BETWEEN date('now') AND date('now','+15 day') ORDER BY e.last_order_date LIMIT 10`).all();
  return c.json({ok:true,orders,plan_pending:pending?.count||0,opportunities:opportunities?.count||0,pending_deliveries:delivery?.count||0,upcoming:upcoming?.count||0,deadlines:deadlines.results});
});

