app.patch('/api/publishers/:id', requireRoles('SUPER_ADMIN','ADMIN'), async c => {
  const b:any=await c.req.json(),rid=c.req.param('id'); const old=await c.env.DB.prepare(`SELECT * FROM publishers WHERE id=?`).bind(rid).first<any>(); if(!old)return fail(c,'Yayınevi bulunamadı.',404);
  await c.env.DB.prepare(`UPDATE publishers SET name=?,short_name=?,logo_url=?,contact_person=?,phone=?,email=?,sales_representative=?,order_contact_info=?,minimum_order=?,default_discount=?,payment_terms=?,delivery_days=?,notes=?,is_active=?,updated_at=? WHERE id=?`)
    .bind(b.name??old.name,b.short_name??old.short_name,b.logo_url===undefined?old.logo_url:b.logo_url,b.contact_person===undefined?old.contact_person:b.contact_person,b.phone===undefined?old.phone:b.phone,b.email===undefined?old.email:b.email,b.sales_representative===undefined?old.sales_representative:b.sales_representative,b.order_contact_info===undefined?old.order_contact_info:b.order_contact_info,Number(b.minimum_order??old.minimum_order),Number(b.default_discount??old.default_discount),b.payment_terms===undefined?old.payment_terms:b.payment_terms,Number(b.delivery_days??old.delivery_days),b.notes===undefined?old.notes:b.notes,b.is_active===undefined?old.is_active:(b.is_active?1:0),now(),rid).run();
  await audit(c.env.DB,c.get('user'),'UPDATE','publisher',rid,old,b); return c.json({ok:true});
});
app.delete('/api/publishers/:id', requireRoles('SUPER_ADMIN','ADMIN'), async c => { const rid=c.req.param('id'); const used=await c.env.DB.prepare(`SELECT id FROM exams WHERE publisher_id=? AND deleted_at IS NULL LIMIT 1`).bind(rid).first(); if(used){await c.env.DB.prepare(`UPDATE publishers SET is_active=0,updated_at=? WHERE id=?`).bind(now(),rid).run();return c.json({ok:true,soft:true});} await c.env.DB.prepare(`UPDATE publishers SET deleted_at=?,is_active=0 WHERE id=?`).bind(now(),rid).run();return c.json({ok:true}); });

