app.get('/api/exams', async c => {
  let sql=`SELECT e.*,p.name publisher_name,p.short_name publisher_short,g.name grade_name,g.code grade_code FROM exams e JOIN publishers p ON p.id=e.publisher_id JOIN grade_levels g ON g.id=e.grade_level_id WHERE e.deleted_at IS NULL`; const vals:any[]=[];
  for(const [key,col] of [['season_id','e.season_id'],['grade_level_id','e.grade_level_id'],['publisher_id','e.publisher_id'],['exam_type','e.exam_type']] as any){const v=c.req.query(key);if(v){sql+=` AND ${col}=?`;vals.push(v)}}
  const status=c.req.query('active');if(status==='1')sql+=' AND e.is_active=1';if(status==='0')sql+=' AND e.is_active=0';const q=c.req.query('q');if(q){sql+=` AND (e.name LIKE ? OR e.code LIKE ? OR p.name LIKE ?)`;vals.push(`%${q}%`,`%${q}%`,`%${q}%`)}sql+=' ORDER BY e.application_start_date,e.name';
  const r=await c.env.DB.prepare(sql).bind(...vals).all();return c.json({ok:true,items:r.results});
});
app.post('/api/exams', requireRoles('SUPER_ADMIN','ADMIN'), async c => { const b:any=await c.req.json(); if(!b.publisher_id||!b.season_id||!b.grade_level_id||!b.name||!b.code)return fail(c,'Yayınevi, sezon, sınıf, ad ve kod gerekli.'); const rid=uid('exam'); await c.env.DB.prepare(`INSERT INTO exams(id,publisher_id,season_id,grade_level_id,name,code,list_price,purchase_price,default_sale_price,minimum_order,last_order_date,estimated_ship_date,application_start_date,application_end_date,description,status,is_active,exam_type,subject,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(rid,b.publisher_id,b.season_id,b.grade_level_id,b.name,b.code,Number(b.list_price||0),Number(b.purchase_price||0),Number(b.default_sale_price||0),Number(b.minimum_order||1),b.last_order_date||null,b.estimated_ship_date||null,b.application_start_date||null,b.application_end_date||null,b.description||null,'ACTIVE',1,b.exam_type||'DENEME',b.subject||null,now(),now()).run(); await audit(c.env.DB,c.get('user'),'CREATE','exam',rid,undefined,b);return c.json({ok:true,id:rid},201); });
app.post('/api/exams/bulk', requireRoles('SUPER_ADMIN','ADMIN'), async c => { const b:any=await c.req.json(); const rows:Array<any>=Array.isArray(b.rows)?b.rows:[]; if(!rows.length)return fail(c,'Yüklenecek satır bulunamadı.'); const errors:any[]=[],created:any[]=[]; const pubs=await c.env.DB.prepare(`SELECT id,name,short_name FROM publishers WHERE deleted_at IS NULL`).all<any>(); const grades=await c.env.DB.prepare(`SELECT id,name,code FROM grade_levels WHERE is_active=1`).all<any>(); const season=b.season_id; for(let i=0;i<rows.length;i++){const x=rows[i];const pub=pubs.results.find((p:any)=>[p.id,p.name,p.short_name].map((v:any)=>String(v).toLowerCase()).includes(String(x.publisher||x.publisher_id||'').toLowerCase()));const grade=grades.results.find((g:any)=>[g.id,g.name,g.code].map((v:any)=>String(v).toLowerCase()).includes(String(x.grade||x.grade_level||x.grade_level_id||'').toLowerCase()));if(!pub||!grade||!x.name||!x.code){errors.push({row:i+2,error:'Yayınevi, sınıf, deneme adı veya kod eksik/eşleşmedi'});continue}try{const rid=uid('exam');await c.env.DB.prepare(`INSERT INTO exams(id,publisher_id,season_id,grade_level_id,name,code,list_price,purchase_price,default_sale_price,minimum_order,last_order_date,estimated_ship_date,application_start_date,application_end_date,status,is_active,exam_type,subject,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,'ACTIVE',1,?,?,?,?)`).bind(rid,pub.id,season,grade.id,x.name,x.code,Math.round(Number(x.list_price||0)*100),Math.round(Number(x.purchase_price||0)*100),Math.round(Number(x.sale_price||x.default_sale_price||0)*100),Number(x.minimum_order||1),x.last_order_date||null,x.estimated_ship_date||null,x.application_start_date||null,x.application_end_date||null,x.exam_type||'DENEME',x.subject||null,now(),now()).run();created.push(rid)}catch(e){errors.push({row:i+2,error:String(e)})}} return c.json({ok:true,created:created.length,errors}); });
app.patch('/api/exams/:id', requireRoles('SUPER_ADMIN','ADMIN'), async c=>{const rid=c.req.param('id'),b:any=await c.req.json();const old=await c.env.DB.prepare(`SELECT * FROM exams WHERE id=?`).bind(rid).first<any>();if(!old)return fail(c,'Deneme bulunamadı.',404);const n={...old,...b};await c.env.DB.prepare(`UPDATE exams SET publisher_id=?,season_id=?,grade_level_id=?,name=?,code=?,list_price=?,purchase_price=?,default_sale_price=?,minimum_order=?,last_order_date=?,estimated_ship_date=?,application_start_date=?,application_end_date=?,description=?,is_active=?,exam_type=?,subject=?,updated_at=? WHERE id=?`).bind(n.publisher_id,n.season_id,n.grade_level_id,n.name,n.code,Number(n.list_price||0),Number(n.purchase_price||0),Number(n.default_sale_price||0),Number(n.minimum_order||1),n.last_order_date||null,n.estimated_ship_date||null,n.application_start_date||null,n.application_end_date||null,n.description||null,n.is_active?1:0,n.exam_type||'DENEME',n.subject||null,now(),rid).run();await audit(c.env.DB,c.get('user'),'UPDATE','exam',rid,old,b);return c.json({ok:true})});
