app.get('/api/digital-assets', async c=>{const u=c.get('user');let sql=`SELECT a.*,e.season_id,e.grade_level_id,e.name exam_name,e.code exam_code,p.id publisher_id,p.name publisher_name,p.short_name publisher_short,g.name grade_name,g.code grade_code FROM digital_exam_assets a JOIN exams e ON e.id=a.exam_id JOIN publishers p ON p.id=e.publisher_id JOIN grade_levels g ON g.id=e.grade_level_id WHERE e.deleted_at IS NULL`;const vals:any[]=[];if(u.role!=='SUPER_ADMIN')sql+=` AND a.is_active=1 AND e.is_active=1`;else{const active=c.req.query('active');if(active==='1')sql+=` AND a.is_active=1`;if(active==='0')sql+=` AND a.is_active=0`}for(const [q,col] of [['season_id','e.season_id'],['publisher_id','e.publisher_id'],['grade_level_id','e.grade_level_id'],['exam_id','e.id']] as any){const v=c.req.query(q);if(v){sql+=` AND ${col}=?`;vals.push(v)}}if(u.role==='KURUM'){sql+=` AND EXISTS(SELECT 1 FROM institution_grade_levels ig WHERE ig.institution_id=? AND ig.grade_level_id=e.grade_level_id)`;vals.push(u.institution_id)}sql+=' ORDER BY g.sort_order,p.name,e.application_start_date,e.name,COALESCE(a.form_code,\'\'),a.asset_type,a.created_at';const r=await c.env.DB.prepare(sql).bind(...vals).all();return c.json({ok:true,items:r.results})});
app.post('/api/digital-assets', requireRoles('SUPER_ADMIN'), async c=>{const u=c.get('user');const form=await c.req.raw.formData();const examId=String(form.get('exam_id')||''),assetType=String(form.get('asset_type')||''),title=String(form.get('title')||'').trim()||null,formatName=String(form.get('format_name')||'').trim()||null,formCode=String(form.get('form_code')||'').trim().toUpperCase()||null,externalUrl=String(form.get('external_url')||'').trim()||null;const allowed=['CEVAP_PDF','KAZANIM_EXCEL','DENEME_PDF','OPTIK_DOKUMAN','SEKONIC','BICOM','DIJITAL_FORMAT','VIDEO_URL'];if(!examId||!allowed.includes(assetType))return fail(c,'Deneme ve geçerli belge türü gerekli.');if(['SEKONIC','BICOM'].includes(assetType)&&!formCode)return fail(c,'Sekonic/Bicom için optik form kodu zorunlu.');const ex=await c.env.DB.prepare(`SELECT e.id,e.code,p.short_name publisher_short,g.code grade_code FROM exams e JOIN publishers p ON p.id=e.publisher_id JOIN grade_levels g ON g.id=e.grade_level_id WHERE e.id=? AND e.deleted_at IS NULL`).bind(examId).first<any>();if(!ex)return fail(c,'Deneme bulunamadı.',404);const dupe=await c.env.DB.prepare(`SELECT id FROM digital_exam_assets WHERE exam_id=? AND asset_type=? AND COALESCE(form_code,'')=COALESCE(?,'') LIMIT 1`).bind(examId,assetType,formCode).first<any>();if(dupe)return fail(c,'Bu deneme/form kodu için aynı belge türü zaten var. Mevcut kaydı düzenleyin.',409);const rid=uid('asset');let storageKey:string|null=null,fileName:string|null=null,contentType:string|null=null,fileSize=0,url:string|null=externalUrl;if(assetType==='VIDEO_URL'){if(!externalUrl)return fail(c,'Video bağlantısı gerekli.');try{const x=new URL(externalUrl);if(!['http:','https:'].includes(x.protocol))throw new Error()}catch{return fail(c,'Geçerli bir http/https bağlantısı girin.')}}else{if(!c.env.MEDIA)return fail(c,'R2 medya alanı bağlı değil.',503);const f=form.get('file');if(!(f instanceof File)||f.size<=0)return fail(c,'Yüklenecek dosya gerekli.');if(f.size>50*1024*1024)return fail(c,'Dosya boyutu en fazla 50 MB olabilir.');fileName=f.name||'dosya';contentType=f.type||'application/octet-stream';fileSize=f.size;const safe=fileName.replace(/[^a-zA-Z0-9._-]+/g,'_').slice(-120)||'dosya';storageKey=`deneme/cevap-anahtarlari/${String(ex.publisher_short||'yayinevi').replace(/[^a-zA-Z0-9_-]+/g,'_')}/${ex.grade_code}/${examId}/${rid}/${safe}`;await c.env.MEDIA.put(storageKey,await f.arrayBuffer(),{httpMetadata:{contentType},customMetadata:{examId,assetType,formCode:formCode||''}});url=null}await c.env.DB.prepare(`INSERT INTO digital_exam_assets(id,exam_id,asset_type,title,format_name,form_code,file_name,content_type,file_size,storage_key,external_url,is_active,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,1,?,?,?)`).bind(rid,examId,assetType,title,formatName,formCode,fileName,contentType,fileSize,storageKey,url,u.id,now(),now()).run();await audit(c.env.DB,u,'CREATE','digital_exam_asset',rid,undefined,{examId,assetType,title,formatName,formCode,fileName,fileSize,externalUrl:url});return c.json({ok:true,id:rid},201)});
app.patch('/api/digital-assets/:id', requireRoles('SUPER_ADMIN'), async c=>{const u=c.get('user'),rid=c.req.param('id'),x:any=await c.req.json();const a=await c.env.DB.prepare(`SELECT * FROM digital_exam_assets WHERE id=?`).bind(rid).first<any>();if(!a)return fail(c,'Belge bulunamadı.',404);const assetType=String(x.asset_type??a.asset_type),formCode=x.form_code===undefined?a.form_code:(String(x.form_code||'').trim().toUpperCase()||null),title=x.title===undefined?a.title:(String(x.title||'').trim()||null),formatName=x.format_name===undefined?a.format_name:(String(x.format_name||'').trim()||null),externalUrl=x.external_url===undefined?a.external_url:(String(x.external_url||'').trim()||null),active=x.is_active===undefined?a.is_active:(x.is_active?1:0);const allowed=['CEVAP_PDF','KAZANIM_EXCEL','DENEME_PDF','OPTIK_DOKUMAN','SEKONIC','BICOM','DIJITAL_FORMAT','VIDEO_URL'];if(!allowed.includes(assetType))return fail(c,'Geçersiz belge türü.');if(['SEKONIC','BICOM'].includes(assetType)&&!formCode)return fail(c,'Sekonic/Bicom için optik form kodu zorunlu.');if(assetType==='VIDEO_URL'){if(!externalUrl)return fail(c,'Video bağlantısı gerekli.');try{const z=new URL(externalUrl);if(!['http:','https:'].includes(z.protocol))throw new Error()}catch{return fail(c,'Geçerli bir http/https bağlantısı girin.')}}const dupe=await c.env.DB.prepare(`SELECT id FROM digital_exam_assets WHERE exam_id=? AND asset_type=? AND COALESCE(form_code,'')=COALESCE(?,'') AND id<>? LIMIT 1`).bind(a.exam_id,assetType,formCode,rid).first<any>();if(dupe)return fail(c,'Bu form kodu için aynı belge türü zaten var.',409);await c.env.DB.prepare(`UPDATE digital_exam_assets SET asset_type=?,title=?,format_name=?,form_code=?,external_url=?,is_active=?,updated_at=? WHERE id=?`).bind(assetType,title,formatName,formCode,externalUrl,active,now(),rid).run();await audit(c.env.DB,u,'UPDATE','digital_exam_asset',rid,a,{assetType,title,formatName,formCode,externalUrl,is_active:active});return c.json({ok:true})});
app.post('/api/digital-assets/:id/replace', requireRoles('SUPER_ADMIN'), async c=>{const u=c.get('user'),rid=c.req.param('id');const a=await c.env.DB.prepare(`SELECT a.*,e.id exam_id,p.short_name publisher_short,g.code grade_code FROM digital_exam_assets a JOIN exams e ON e.id=a.exam_id JOIN publishers p ON p.id=e.publisher_id JOIN grade_levels g ON g.id=e.grade_level_id WHERE a.id=?`).bind(rid).first<any>();if(!a)return fail(c,'Belge bulunamadı.',404);if(a.asset_type==='VIDEO_URL')return fail(c,'Video bağlantısı dosya ile değiştirilemez.');if(!c.env.MEDIA)return fail(c,'R2 medya alanı bağlı değil.',503);const form=await c.req.raw.formData();const f=form.get('file');if(!(f instanceof File)||f.size<=0)return fail(c,'Yeni dosya gerekli.');if(f.size>50*1024*1024)return fail(c,'Dosya boyutu en fazla 50 MB olabilir.');const safe=(f.name||'dosya').replace(/[^a-zA-Z0-9._-]+/g,'_').slice(-120)||'dosya';const newKey=`deneme/cevap-anahtarlari/${String(a.publisher_short||'yayinevi').replace(/[^a-zA-Z0-9_-]+/g,'_')}/${a.grade_code}/${a.exam_id}/${rid}/${Date.now()}-${safe}`;await c.env.MEDIA.put(newKey,await f.arrayBuffer(),{httpMetadata:{contentType:f.type||'application/octet-stream'},customMetadata:{examId:a.exam_id,assetType:a.asset_type,formCode:a.form_code||''}});if(a.storage_key&&a.storage_key!==newKey)await c.env.MEDIA.delete(a.storage_key);await c.env.DB.prepare(`UPDATE digital_exam_assets SET file_name=?,content_type=?,file_size=?,storage_key=?,external_url=NULL,updated_at=? WHERE id=?`).bind(f.name||'dosya',f.type||'application/octet-stream',f.size,newKey,now(),rid).run();await audit(c.env.DB,u,'REPLACE_FILE','digital_exam_asset',rid,{file_name:a.file_name,storage_key:a.storage_key},{file_name:f.name,storage_key:newKey});return c.json({ok:true})});
app.get('/api/digital-assets/:id/download', async c=>{const u=c.get('user'),rid=c.req.param('id');const a=await c.env.DB.prepare(`SELECT a.*,e.grade_level_id,e.is_active exam_active FROM digital_exam_assets a JOIN exams e ON e.id=a.exam_id WHERE a.id=?`).bind(rid).first<any>();if(!a)return fail(c,'Dosya bulunamadı.',404);if(u.role!=='SUPER_ADMIN'&&(!a.is_active||!a.exam_active))return fail(c,'Dosya yayında değil.',404);if(u.role==='KURUM'){const ok=await c.env.DB.prepare(`SELECT id FROM institution_grade_levels WHERE institution_id=? AND grade_level_id=?`).bind(u.institution_id,a.grade_level_id).first();if(!ok)return fail(c,'Bu dosyaya erişim yetkiniz yok.',403)}if(a.external_url)return c.redirect(a.external_url);if(!c.env.MEDIA||!a.storage_key)return fail(c,'Dosya depolama alanında bulunamadı.',404);const obj=await c.env.MEDIA.get(a.storage_key);if(!obj)return fail(c,'Dosya R2 alanında bulunamadı.',404);const h=new Headers();obj.writeHttpMetadata(h);h.set('etag',obj.httpEtag);h.set('Content-Type',a.content_type||h.get('Content-Type')||'application/octet-stream');h.set('Content-Disposition',`attachment; filename*=UTF-8''${encodeURIComponent(a.file_name||'dosya')}`);return new Response(obj.body,{headers:h})});
app.delete('/api/digital-assets/:id', requireRoles('SUPER_ADMIN'), async c=>{const u=c.get('user'),rid=c.req.param('id');const a=await c.env.DB.prepare(`SELECT * FROM digital_exam_assets WHERE id=?`).bind(rid).first<any>();if(!a)return fail(c,'Belge bulunamadı.',404);if(a.storage_key&&c.env.MEDIA)await c.env.MEDIA.delete(a.storage_key);await c.env.DB.prepare(`DELETE FROM digital_exam_assets WHERE id=?`).bind(rid).run();await audit(c.env.DB,u,'DELETE','digital_exam_asset',rid,a,undefined);return c.json({ok:true})});

// INSTITUTIONS
app.get('/api/institutions', async c=>{const u=c.get('user');let sql=`SELECT i.*,u.full_name staff_name,(SELECT group_concat(grade_level_id) FROM institution_grade_levels ig WHERE ig.institution_id=i.id) grade_ids,(SELECT login_code FROM users ku WHERE ku.institution_id=i.id AND ku.role='KURUM' AND ku.deleted_at IS NULL LIMIT 1) login_code FROM institutions i LEFT JOIN users u ON u.id=i.staff_id WHERE i.deleted_at IS NULL`;const vals:any[]=[];if(u.role==='KURUM'){sql+=' AND i.id=?';vals.push(u.institution_id)}if(u.role==='PERSONEL'){sql+=' AND i.staff_id=?';vals.push(u.id)}const active=c.req.query('active');if(active==='1')sql+=' AND i.is_active=1';if(active==='0')sql+=' AND i.is_active=0';const q=c.req.query('q');if(q){sql+=' AND (i.name LIKE ? OR i.code LIKE ? OR i.district LIKE ?)';vals.push(`%${q}%`,`%${q}%`,`%${q}%`)}sql+=' ORDER BY i.name';const r=await c.env.DB.prepare(sql).bind(...vals).all<any>();return c.json({ok:true,items:(r.results||[]).map((x:any)=>({...x,grade_level_ids:x.grade_ids?String(x.grade_ids).split(','):[]}))})});
app.post('/api/institutions', requireRoles('SUPER_ADMIN','ADMIN'), async c=>{const b:any=await c.req.json();if(!b.name||!b.code)return fail(c,'Kurum adı ve kurum kodu gerekli.');if(!b.portal_password)return fail(c,'Kurum ilk oluşturulurken kurum giriş şifresi gerekli.');const code=normalizeCode(b.code),rid=uid('inst');let staff=b.staff_id||null;if(!staff)staff=await fallbackOwner(c.env.DB,rid);await c.env.DB.prepare(`INSERT INTO institutions(id,erp_external_id,name,code,type,is_private,province,district,phone,email,contact_person,staff_id,estimated_capacity,is_active,notes,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,1,?,?,?)`).bind(rid,b.erp_external_id||null,b.name,code,b.type||null,b.is_private===false?0:1,b.province||'İstanbul',b.district||null,b.phone||null,b.email||null,b.contact_person||null,staff,Number(b.estimated_capacity||0),b.notes||null,now(),now()).run();for(const gid of (b.grade_level_ids||[]))await c.env.DB.prepare(`INSERT OR IGNORE INTO institution_grade_levels(id,institution_id,grade_level_id,created_at) VALUES(?,?,?,?)`).bind(uid('igl'),rid,gid,now()).run();if(!staff){const admin=await fallbackOwner(c.env.DB,rid);if(admin)await c.env.DB.prepare(`UPDATE institutions SET staff_id=? WHERE id=?`).bind(admin,rid).run()}try{await upsertInstitutionPortalUser(c.env.DB,{id:rid,name:b.name,code},b.portal_password)}catch(e){return fail(c,String(e),400)}await audit(c.env.DB,c.get('user'),'CREATE','institution',rid,undefined,b);return c.json({ok:true,id:rid},201)});
app.patch('/api/institutions/:id', requireRoles('SUPER_ADMIN','ADMIN'), async c=>{const rid=c.req.param('id'),b:any=await c.req.json();const old=await c.env.DB.prepare(`SELECT * FROM institutions WHERE id=?`).bind(rid).first<any>();if(!old)return fail(c,'Kurum bulunamadı.',404);let staff=b.staff_id===undefined?old.staff_id:b.staff_id;if(!staff){const admin=await c.env.DB.prepare(`SELECT id FROM users WHERE role='SUPER_ADMIN' AND status='ACTIVE' AND deleted_at IS NULL ORDER BY created_at LIMIT 1`).first<{id:string}>();staff=admin?.id||null;}const n={...old,...b,staff_id:staff,code:normalizeCode(b.code??old.code)};await c.env.DB.prepare(`UPDATE institutions SET erp_external_id=?,name=?,code=?,type=?,is_private=?,province=?,district=?,phone=?,email=?,contact_person=?,staff_id=?,estimated_capacity=?,is_active=?,notes=?,updated_at=? WHERE id=?`).bind(n.erp_external_id||null,n.name,n.code,n.type||null,n.is_private?1:0,n.province||null,n.district||null,n.phone||null,n.email||null,n.contact_person||null,n.staff_id||null,Number(n.estimated_capacity||0),n.is_active?1:0,n.notes||null,now(),rid).run();await c.env.DB.prepare(`UPDATE users SET login_code=?,updated_at=? WHERE institution_id=? AND role='KURUM' AND deleted_at IS NULL`).bind(n.code,now(),rid).run();if(Array.isArray(b.grade_level_ids)){await c.env.DB.prepare(`DELETE FROM institution_grade_levels WHERE institution_id=?`).bind(rid).run();for(const gid of b.grade_level_ids)await c.env.DB.prepare(`INSERT OR IGNORE INTO institution_grade_levels(id,institution_id,grade_level_id,created_at) VALUES(?,?,?,?)`).bind(uid('igl'),rid,gid,now()).run()}if(b.portal_password)await upsertInstitutionPortalUser(c.env.DB,{id:rid,name:n.name,code:n.code},b.portal_password);await c.env.DB.prepare(`UPDATE sales_opportunities SET staff_id=? WHERE institution_id=? AND status NOT IN ('SIPARIS_VERDI','ILGILENMIYOR','BASKA_YAYINEVI_ALDI','KATILMAYACAK')`).bind(n.staff_id,rid).run();await audit(c.env.DB,c.get('user'),'UPDATE','institution',rid,old,b);return c.json({ok:true})});
app.delete('/api/institutions/:id', requireRoles('SUPER_ADMIN','ADMIN'), async c=>{const rid=c.req.param('id');const used=await c.env.DB.prepare(`SELECT id FROM orders WHERE institution_id=? LIMIT 1`).bind(rid).first();if(used){await c.env.DB.prepare(`UPDATE institutions SET is_active=0,updated_at=? WHERE id=?`).bind(now(),rid).run();return c.json({ok:true,soft:true})}await c.env.DB.prepare(`UPDATE institutions SET deleted_at=?,is_active=0 WHERE id=?`).bind(now(),rid).run();return c.json({ok:true})});

app.get('/api/erp/status', c=>c.json({ok:true,configured:!!c.env.ERP_BASE_URL,base_url:c.env.ERP_BASE_URL||null}));
app.get('/api/erp/institutions', requireRoles('SUPER_ADMIN','ADMIN'), async c=>{if(!c.env.ERP_BASE_URL)return c.json({ok:true,configured:false,items:[],message:'ERP bağlantısı tanımlı değil; manuel kurum ekleme kullanılabilir.'});const path=c.env.ERP_CUSTOMERS_PATH||'/api/customers';const url=new URL(path,c.env.ERP_BASE_URL);const q=c.req.query('q');if(q)url.searchParams.set('q',q);try{const r=await fetch(url.toString(),{headers:{Accept:'application/json'}});if(!r.ok)throw new Error(`ERP ${r.status}`);const d:any=await r.json();return c.json({ok:true,configured:true,items:d.items||d.customers||d.data||[]})}catch(e){return c.json({ok:true,configured:true,items:[],message:`ERP carileri alınamadı: ${String(e)}`})}});

// PLANS + CALENDARS
app.get('/api/plans', async c=>{const u=c.get('user'),inst=u.role==='KURUM'?u.institution_id:c.req.query('institution_id');if(!inst)return fail(c,'Kurum gerekli.');if(!(await institutionAllowed(c.env.DB,u,inst!)))return fail(c,'Yetkisiz.',403);let sql=`SELECT p.*,e.name exam_name,e.code exam_code,e.application_start_date,e.application_end_date,e.last_order_date,e.exam_type,e.subject,g.name grade_name,g.code grade_code,pub.name publisher_name,pub.short_name publisher_short,cal.institution_application_date,o.id order_id,o.status order_status,o.quantity order_quantity FROM institution_exam_plans p JOIN exams e ON e.id=p.exam_id JOIN grade_levels g ON g.id=p.grade_level_id JOIN publishers pub ON pub.id=e.publisher_id LEFT JOIN institution_calendars cal ON cal.institution_id=p.institution_id AND cal.exam_id=p.exam_id LEFT JOIN orders o ON o.institution_id=p.institution_id AND o.exam_id=p.exam_id AND o.status!='IPTAL' WHERE p.institution_id=?`;const vals:any[]=[inst];const season=c.req.query('season_id');if(season){sql+=' AND p.season_id=?';vals.push(season)}const month=c.req.query('month');if(month){sql+=` AND substr(COALESCE(cal.institution_application_date,e.application_start_date),6,2)=?`;vals.push(month)}sql+=' ORDER BY COALESCE(cal.institution_application_date,e.application_start_date),g.sort_order';const r=await c.env.DB.prepare(sql).bind(...vals).all();return c.json({ok:true,items:r.results})});
app.post('/api/plans', async c=>{const u=c.get('user'),b:any=await c.req.json(),inst=u.role==='KURUM'?u.institution_id:b.institution_id;if(!inst)return fail(c,'Kurum gerekli.');if(!(await institutionAllowed(c.env.DB,u,inst)))return fail(c,'Bu kurum için plan oluşturamazsınız.',403);const items:Array<any>=Array.isArray(b.items)?b.items:[];if(!items.length)return fail(c,'En az bir deneme seçiniz.');if(items.some(x=>!x.exam_id||Number(x.planned_quantity)<=0))return fail(c,'Tüm seçili denemeler için adet 0’dan büyük olmalı.');let added=0;for(const item of items){const ex=await c.env.DB.prepare(`SELECT * FROM exams WHERE id=? AND is_active=1 AND deleted_at IS NULL`).bind(item.exam_id).first<any>();if(!ex)continue;const permitted=await c.env.DB.prepare(`SELECT id FROM institution_grade_levels WHERE institution_id=? AND grade_level_id=?`).bind(inst,ex.grade_level_id).first();if(!permitted)return fail(c,`${ex.name} için kurumun bu sınıf düzeyi aktif değil.`);const pid=uid('plan');const res=await c.env.DB.prepare(`INSERT OR IGNORE INTO institution_exam_plans(id,institution_id,season_id,exam_id,grade_level_id,status,planned_quantity,notes,created_at,updated_at) VALUES(?,?,?,?,?,'SIPARIS_BEKLIYOR',?,?,?,?)`).bind(pid,inst,ex.season_id,ex.id,ex.grade_level_id,Number(item.planned_quantity),item.notes||null,now(),now()).run();if((res.meta?.changes||0)>0){added++;await c.env.DB.prepare(`INSERT OR IGNORE INTO institution_calendars(id,institution_id,season_id,exam_id,publisher_application_start,publisher_application_end,institution_application_date,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?)`).bind(uid('cal'),inst,ex.season_id,ex.id,ex.application_start_date,ex.application_end_date,item.institution_application_date||null,now(),now()).run();const owner=await fallbackOwner(c.env.DB,inst);if(owner)await c.env.DB.prepare(`INSERT OR IGNORE INTO sales_opportunities(id,institution_id,exam_id,staff_id,priority,status,notes,created_at,updated_at) VALUES(?,?,?,?,?,'ARANACAK','Planlandı fakat siparişe dönüşmedi',?,?)`).bind(uid('opp'),inst,ex.id,owner,'HIGH',now(),now()).run()}}return c.json({ok:true,added})});
app.patch('/api/plans/:id', async c=>{const u=c.get('user'),rid=c.req.param('id'),b:any=await c.req.json();const row=await c.env.DB.prepare(`SELECT * FROM institution_exam_plans WHERE id=?`).bind(rid).first<any>();if(!row)return fail(c,'Plan bulunamadı.',404);if(!(await institutionAllowed(c.env.DB,u,row.institution_id)))return fail(c,'Yetkisiz.',403);if(b.planned_quantity!==undefined&&Number(b.planned_quantity)<=0)return fail(c,'Planlanan adet 0’dan büyük olmalı.');if(b.institution_application_date!==undefined){const ex=await c.env.DB.prepare(`SELECT application_start_date,application_end_date FROM exams WHERE id=?`).bind(row.exam_id).first<any>();const d=b.institution_application_date;const outside=d&&ex?.application_start_date&&ex?.application_end_date&&(d<ex.application_start_date||d>ex.application_end_date);if(outside){const setting=await c.env.DB.prepare(`SELECT value FROM system_settings WHERE key='allow_drag_drop_outside_range'`).first<any>();if(setting?.value!=='1')return fail(c,`Seçilen tarih yayınevinin ${ex.application_start_date} – ${ex.application_end_date} aralığının dışında.`)}await c.env.DB.prepare(`UPDATE institution_calendars SET institution_application_date=?,updated_at=? WHERE institution_id=? AND exam_id=?`).bind(d||null,now(),row.institution_id,row.exam_id).run()}await c.env.DB.prepare(`UPDATE institution_exam_plans SET planned_quantity=COALESCE(?,planned_quantity),notes=COALESCE(?,notes),status=COALESCE(?,status),updated_at=? WHERE id=?`).bind(b.planned_quantity??null,b.notes??null,b.status??null,now(),rid).run();await audit(c.env.DB,u,'UPDATE','institution_exam_plan',rid,row,b);return c.json({ok:true})});
app.delete('/api/plans/:id', async c=>{const u=c.get('user'),rid=c.req.param('id');const row=await c.env.DB.prepare(`SELECT * FROM institution_exam_plans WHERE id=?`).bind(rid).first<any>();if(!row)return fail(c,'Plan bulunamadı.',404);if(!(await institutionAllowed(c.env.DB,u,row.institution_id)))return fail(c,'Yetkisiz.',403);const order=await c.env.DB.prepare(`SELECT id FROM orders WHERE institution_id=? AND exam_id=? AND status!='IPTAL'`).bind(row.institution_id,row.exam_id).first();if(order)return fail(c,'Bu deneme için aktif sipariş var; önce siparişi iptal edin.');await c.env.DB.prepare(`DELETE FROM institution_calendars WHERE institution_id=? AND exam_id=?`).bind(row.institution_id,row.exam_id).run();await c.env.DB.prepare(`DELETE FROM sales_opportunities WHERE institution_id=? AND exam_id=?`).bind(row.institution_id,row.exam_id).run();await c.env.DB.prepare(`DELETE FROM institution_exam_plans WHERE id=?`).bind(rid).run();return c.json({ok:true})});

