app.get('/api/opportunities', requireRoles('SUPER_ADMIN','ADMIN','PERSONEL'), async c=>{const u=c.get('user');let sql=`SELECT so.*,i.name institution_name,i.district,e.name exam_name,e.last_order_date,p.name publisher_name,g.name grade_name,usr.full_name staff_name FROM sales_opportunities so JOIN institutions i ON i.id=so.institution_id JOIN exams e ON e.id=so.exam_id JOIN publishers p ON p.id=e.publisher_id JOIN grade_levels g ON g.id=e.grade_level_id LEFT JOIN users usr ON usr.id=so.staff_id WHERE 1=1`;const vals:any[]=[];if(u.role==='PERSONEL'){sql+=' AND so.staff_id=?';vals.push(u.id)}if(u.role==='KURUM'){sql+=' AND so.institution_id=?';vals.push(u.institution_id)}sql+=` ORDER BY CASE so.priority WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 ELSE 3 END,e.last_order_date`;const r=await c.env.DB.prepare(sql).bind(...vals).all();return c.json({ok:true,items:r.results})});
app.post('/api/opportunities/generate', requireRoles('SUPER_ADMIN','ADMIN'), async c=>{const r=await c.env.DB.prepare(`SELECT p.institution_id,p.exam_id,e.last_order_date FROM institution_exam_plans p JOIN exams e ON e.id=p.exam_id LEFT JOIN orders o ON o.institution_id=p.institution_id AND o.exam_id=p.exam_id AND o.status!='IPTAL' WHERE o.id IS NULL`).all<any>();let added=0;for(const x of r.results){const owner=await fallbackOwner(c.env.DB,x.institution_id);if(!owner)continue;const days=x.last_order_date?Math.ceil((new Date(`${x.last_order_date}T12:00:00`).getTime()-Date.now())/86400000):99;const priority=days<=7?'HIGH':days<=15?'MEDIUM':'LOW';const rr=await c.env.DB.prepare(`INSERT OR IGNORE INTO sales_opportunities(id,institution_id,exam_id,staff_id,priority,status,notes,created_at,updated_at) VALUES(?,?,?,?,?,'ARANACAK','Planlandı fakat siparişe dönüşmedi',?,?)`).bind(uid('opp'),x.institution_id,x.exam_id,owner,priority,now(),now()).run();added+=rr.meta?.changes||0}return c.json({ok:true,added})});
app.patch('/api/opportunities/:id', requireRoles('SUPER_ADMIN','ADMIN','PERSONEL'), async c=>{const u=c.get('user'),rid=c.req.param('id'),b:any=await c.req.json();const row=await c.env.DB.prepare(`SELECT * FROM sales_opportunities WHERE id=?`).bind(rid).first<any>();if(!row)return fail(c,'Fırsat bulunamadı.',404);if(u.role==='PERSONEL'&&row.staff_id!==u.id)return fail(c,'Yetkisiz.',403);await c.env.DB.prepare(`UPDATE sales_opportunities SET status=COALESCE(?,status),priority=COALESCE(?,priority),notes=COALESCE(?,notes),loss_reason=COALESCE(?,loss_reason),updated_at=? WHERE id=?`).bind(b.status??null,b.priority??null,b.notes??null,b.loss_reason??null,now(),rid).run();return c.json({ok:true})});
app.get('/api/order-pending', async c=>{const u=c.get('user');let sql=`SELECT p.id plan_id,p.institution_id,p.exam_id,p.planned_quantity,p.status,i.name institution_name,i.staff_id,e.name exam_name,e.code exam_code,e.default_sale_price,e.last_order_date,pub.name publisher_name,pub.short_name publisher_short,g.name grade_name FROM institution_exam_plans p JOIN institutions i ON i.id=p.institution_id JOIN exams e ON e.id=p.exam_id JOIN publishers pub ON pub.id=e.publisher_id JOIN grade_levels g ON g.id=e.grade_level_id LEFT JOIN orders o ON o.institution_id=p.institution_id AND o.exam_id=p.exam_id AND o.status!='IPTAL' WHERE o.id IS NULL AND p.planned_quantity IS NOT NULL AND p.planned_quantity>0`;const vals:any[]=[];if(u.role==='KURUM'){sql+=' AND p.institution_id=?';vals.push(u.institution_id)}if(u.role==='PERSONEL'){sql+=' AND i.staff_id=?';vals.push(u.id)}sql+=' ORDER BY e.last_order_date,i.name';const r=await c.env.DB.prepare(sql).bind(...vals).all();return c.json({ok:true,items:r.results})});

