app.get('/api/orders', async c=>{const u=c.get('user');let sql=`SELECT o.*,i.name institution_name,e.name exam_name,e.code exam_code,e.estimated_ship_date,e.application_start_date,e.application_end_date,p.name publisher_name,g.name grade_name,usr.full_name staff_name FROM orders o JOIN institutions i ON i.id=o.institution_id JOIN exams e ON e.id=o.exam_id JOIN publishers p ON p.id=e.publisher_id JOIN grade_levels g ON g.id=o.grade_level_id LEFT JOIN users usr ON usr.id=o.staff_id WHERE 1=1`;const vals:any[]=[];if(u.role==='KURUM'){sql+=' AND o.institution_id=?';vals.push(u.institution_id)}if(u.role==='PERSONEL'){sql+=' AND o.staff_id=?';vals.push(u.id)}sql+=' ORDER BY o.created_at DESC';const r=await c.env.DB.prepare(sql).bind(...vals).all();return c.json({ok:true,items:r.results})});
app.post('/api/orders', async c=>{const u=c.get('user'),b:any=await c.req.json();const inst=u.role==='KURUM'?u.institution_id:b.institution_id;if(!inst||!b.exam_id||Number(b.quantity)<=0)return fail(c,'Kurum, deneme ve adet gerekli.');if(!(await institutionAllowed(c.env.DB,u,inst)))return fail(c,'Bu kurum için sipariş oluşturamazsınız.',403);const ex=await c.env.DB.prepare(`SELECT * FROM exams WHERE id=? AND deleted_at IS NULL`).bind(b.exam_id).first<any>();if(!ex)return fail(c,'Deneme bulunamadı.',404);const active=await c.env.DB.prepare(`SELECT id FROM orders WHERE institution_id=? AND exam_id=? AND status!='IPTAL'`).bind(inst,ex.id).first();if(active)return fail(c,'Bu kurum ve deneme için zaten aktif sipariş var.');const qty=Number(b.quantity),unit=Number(b.unit_price??ex.default_sale_price),owner=await fallbackOwner(c.env.DB,inst);const rid=uid('ord');await c.env.DB.prepare(`INSERT INTO orders(id,institution_id,exam_id,season_id,grade_level_id,quantity,unit_price,total_price,staff_id,status,notes,confirmed_at,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,'ONAYLANDI',?,?,?,?)`).bind(rid,inst,ex.id,ex.season_id,ex.grade_level_id,qty,unit,qty*unit,owner,b.notes||null,now(),now(),now()).run();await c.env.DB.prepare(`UPDATE institution_exam_plans SET status='SIPARIS_VERILDI',planned_quantity=?,updated_at=? WHERE institution_id=? AND exam_id=?`).bind(qty,now(),inst,ex.id).run();await c.env.DB.prepare(`UPDATE sales_opportunities SET status='SIPARIS_VERDI',updated_at=? WHERE institution_id=? AND exam_id=?`).bind(now(),inst,ex.id).run();await audit(c.env.DB,u,'CREATE','order',rid,undefined,b);return c.json({ok:true,id:rid},201)});
app.patch('/api/orders/:id', async c=>{const u=c.get('user'),rid=c.req.param('id'),b:any=await c.req.json();const row=await c.env.DB.prepare(`SELECT * FROM orders WHERE id=?`).bind(rid).first<any>();if(!row)return fail(c,'Sipariş bulunamadı.',404);if(!(await institutionAllowed(c.env.DB,u,row.institution_id)))return fail(c,'Yetkisiz.',403);if(u.role==='KURUM'&&!['ONAYLANDI','SIPARIS_ALINDI'].includes(row.status))return fail(c,'Operasyona alınmış siparişi kurum değiştiremez.',403);const qty=b.quantity===undefined?row.quantity:Number(b.quantity),unit=b.unit_price===undefined?row.unit_price:Number(b.unit_price);if(qty<=0)return fail(c,'Adet 0’dan büyük olmalı.');const sent=b.sent_to_institution===true?(row.sent_to_institution_at||now()):b.sent_to_institution===false?null:row.sent_to_institution_at;const delivered=b.delivered===true?(row.delivered_at||now()):b.delivered===false?null:row.delivered_at;const applied=b.exam_applied===true?(row.exam_applied_at||now()):b.exam_applied===false?null:row.exam_applied_at;await c.env.DB.prepare(`UPDATE orders SET quantity=?,unit_price=?,total_price=?,status=?,notes=?,sent_to_institution_at=?,delivered_at=?,exam_applied_at=?,exam_applied_by=?,updated_at=? WHERE id=?`).bind(qty,unit,qty*unit,b.status??row.status,b.notes===undefined?row.notes:b.notes,sent,delivered,applied,applied?u.id:null,now(),rid).run();await audit(c.env.DB,u,'UPDATE','order',rid,row,b);return c.json({ok:true})});
app.delete('/api/orders/:id', async c=>{const u=c.get('user'),rid=c.req.param('id');const row=await c.env.DB.prepare(`SELECT * FROM orders WHERE id=?`).bind(rid).first<any>();if(!row)return fail(c,'Sipariş bulunamadı.',404);if(!(await institutionAllowed(c.env.DB,u,row.institution_id)))return fail(c,'Yetkisiz.',403);const downstream=await c.env.DB.prepare(`SELECT id FROM publisher_order_allocations WHERE order_id=? LIMIT 1`).bind(rid).first()||await c.env.DB.prepare(`SELECT id FROM deliveries WHERE order_id=? LIMIT 1`).bind(rid).first();if(downstream){await c.env.DB.prepare(`UPDATE orders SET status='IPTAL',updated_at=? WHERE id=?`).bind(now(),rid).run();return c.json({ok:true,cancelled:true})}await c.env.DB.prepare(`DELETE FROM orders WHERE id=?`).bind(rid).run();await c.env.DB.prepare(`UPDATE institution_exam_plans SET status='SIPARIS_BEKLIYOR',updated_at=? WHERE institution_id=? AND exam_id=?`).bind(now(),row.institution_id,row.exam_id).run();return c.json({ok:true,deleted:true})});

