app.get('/api/order-lists/preview', requireRoles('SUPER_ADMIN','ADMIN','OPERASYON'), async c=>{const r=await c.env.DB.prepare(`SELECT e.publisher_id,p.name publisher_name,p.short_name publisher_short,o.exam_id,e.name exam_name,e.code exam_code,g.name grade_name,e.last_order_date,COUNT(*) institution_count,SUM(o.quantity) total_quantity FROM orders o JOIN exams e ON e.id=o.exam_id JOIN publishers p ON p.id=e.publisher_id JOIN grade_levels g ON g.id=e.grade_level_id LEFT JOIN publisher_order_allocations a ON a.order_id=o.id WHERE o.status IN ('ONAYLANDI','SIPARIS_ALINDI') AND a.id IS NULL GROUP BY e.publisher_id,o.exam_id ORDER BY e.last_order_date,p.name`).all();return c.json({ok:true,items:r.results})});
app.get('/api/publisher-orders', requireRoles('SUPER_ADMIN','ADMIN','OPERASYON'), async c=>{const r=await c.env.DB.prepare(`SELECT po.*,p.name publisher_name,p.short_name publisher_short,e.name exam_name,e.code exam_code,g.name grade_name FROM publisher_orders po JOIN publishers p ON p.id=po.publisher_id JOIN exams e ON e.id=po.exam_id JOIN grade_levels g ON g.id=e.grade_level_id ORDER BY po.created_at DESC`).all();return c.json({ok:true,items:r.results})});
app.post('/api/publisher-orders', requireRoles('SUPER_ADMIN','ADMIN','OPERASYON'), async c=>{const u=c.get('user'),b:any=await c.req.json();const examId=b.exam_id;if(!examId)return fail(c,'Deneme gerekli.');const rows=await c.env.DB.prepare(`SELECT o.*,e.publisher_id FROM orders o JOIN exams e ON e.id=o.exam_id LEFT JOIN publisher_order_allocations a ON a.order_id=o.id WHERE o.exam_id=? AND o.status IN ('ONAYLANDI','SIPARIS_ALINDI') AND a.id IS NULL`).bind(examId).all<any>();if(!rows.results.length)return fail(c,'Sipariş listesine eklenecek kurum siparişi yok.');const total=rows.results.reduce((s:any,x:any)=>s+Number(x.quantity),0),rid=uid('po');await c.env.DB.prepare(`INSERT INTO publisher_orders(id,publisher_id,exam_id,total_quantity,order_date,received_quantity,missing_quantity,status,created_at,updated_at) VALUES(?,?,?,?,?,0,?,'LISTE_OLUSTURULDU',?,?)`).bind(rid,rows.results[0].publisher_id,examId,total,today(),total,now(),now()).run();for(const x of rows.results){await c.env.DB.prepare(`INSERT INTO publisher_order_allocations(id,publisher_order_id,order_id,quantity,created_at) VALUES(?,?,?,?,?)`).bind(uid('poa'),rid,x.id,x.quantity,now()).run();await c.env.DB.prepare(`UPDATE orders SET status='SIPARIS_LISTESINDE',updated_at=? WHERE id=?`).bind(now(),x.id).run()}await audit(c.env.DB,u,'CREATE','publisher_order_list',rid,undefined,{examId,total});return c.json({ok:true,id:rid,total},201)});
app.patch('/api/publisher-orders/:id', requireRoles('SUPER_ADMIN','ADMIN','OPERASYON'), async c=>{const rid=c.req.param('id'),b:any=await c.req.json();const row=await c.env.DB.prepare(`SELECT * FROM publisher_orders WHERE id=?`).bind(rid).first<any>();if(!row)return fail(c,'Sipariş listesi bulunamadı.',404);const status=b.status??row.status,b2bAt=status==='B2B_SIPARISI_VERILDI'?(row.b2b_ordered_at||now()):row.b2b_ordered_at;await c.env.DB.prepare(`UPDATE publisher_orders SET status=?,order_number=?,invoice_number=?,courier=?,tracking_number=?,b2b_ordered_at=?,b2b_notes=?,updated_at=? WHERE id=?`).bind(status,b.order_number??row.order_number,b.invoice_number??row.invoice_number,b.courier??row.courier,b.tracking_number??row.tracking_number,b2bAt,b.b2b_notes??row.b2b_notes,now(),rid).run();if(status==='B2B_SIPARISI_VERILDI'){const alloc=await c.env.DB.prepare(`SELECT order_id FROM publisher_order_allocations WHERE publisher_order_id=?`).bind(rid).all<any>();for(const a of alloc.results)await c.env.DB.prepare(`UPDATE orders SET status='B2B_SIPARISI_VERILDI',updated_at=? WHERE id=?`).bind(now(),a.order_id).run()}return c.json({ok:true})});
app.post('/api/goods-receipts', requireRoles('SUPER_ADMIN','ADMIN','OPERASYON'), async c=>{const b:any=await c.req.json();if(!b.publisher_order_id||Number(b.received_quantity)<=0)return fail(c,'Sipariş listesi ve gelen adet gerekli.');const po=await c.env.DB.prepare(`SELECT * FROM publisher_orders WHERE id=?`).bind(b.publisher_order_id).first<any>();if(!po)return fail(c,'Sipariş listesi bulunamadı.',404);const incoming=Number(b.received_quantity),newReceived=Number(po.received_quantity||0)+incoming,missing=Math.max(0,Number(po.total_quantity)-newReceived),status=missing===0?'TAM_GELDI':'KISMI_GELDI';await c.env.DB.prepare(`INSERT INTO goods_receipts(id,publisher_order_id,received_date,received_quantity,missing_quantity,notes,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?)`).bind(uid('gr'),po.id,b.received_date||today(),incoming,missing,b.notes||null,status,now(),now()).run();await c.env.DB.prepare(`UPDATE publisher_orders SET received_quantity=?,missing_quantity=?,status=?,updated_at=? WHERE id=?`).bind(newReceived,missing,status,now(),po.id).run();if(missing===0){const alloc=await c.env.DB.prepare(`SELECT order_id FROM publisher_order_allocations WHERE publisher_order_id=?`).bind(po.id).all<any>();for(const a of alloc.results)await c.env.DB.prepare(`UPDATE orders SET status='URUN_GELDI',updated_at=? WHERE id=?`).bind(now(),a.order_id).run()}return c.json({ok:true,received:newReceived,missing,status})});

