app.get('/api/reports/summary', requireRoles('SUPER_ADMIN','ADMIN','PERSONEL'), async c=>{const db=c.env.DB;const planned=await db.prepare(`SELECT COUNT(*) total,SUM(CASE WHEN EXISTS(SELECT 1 FROM orders o WHERE o.institution_id=p.institution_id AND o.exam_id=p.exam_id AND o.status!='IPTAL') THEN 1 ELSE 0 END) converted FROM institution_exam_plans p`).first<any>();const byPublisher=await db.prepare(`SELECT p.name label,COUNT(o.id) orders,SUM(o.quantity) quantity,SUM(o.total_price) revenue FROM orders o JOIN exams e ON e.id=o.exam_id JOIN publishers p ON p.id=e.publisher_id WHERE o.status!='IPTAL' GROUP BY p.id ORDER BY revenue DESC`).all();const byGrade=await db.prepare(`SELECT g.name label,COUNT(o.id) orders,SUM(o.quantity) quantity,SUM(o.total_price) revenue FROM orders o JOIN grade_levels g ON g.id=o.grade_level_id WHERE o.status!='IPTAL' GROUP BY g.id ORDER BY g.sort_order`).all();const losses=await db.prepare(`SELECT COALESCE(loss_reason,'Belirtilmedi') label,COUNT(*) count FROM sales_opportunities WHERE status IN ('ILGILENMIYOR','BASKA_YAYINEVI_ALDI','KATILMAYACAK','ULASILAMADI') GROUP BY COALESCE(loss_reason,'Belirtilmedi') ORDER BY count DESC`).all();const applied=await db.prepare(`SELECT COUNT(*) total,SUM(CASE WHEN sent_to_institution_at IS NOT NULL THEN 1 ELSE 0 END) sent,SUM(CASE WHEN delivered_at IS NOT NULL OR status='TESLIM_EDILDI' THEN 1 ELSE 0 END) delivered,SUM(CASE WHEN exam_applied_at IS NOT NULL THEN 1 ELSE 0 END) applied FROM orders WHERE status!='IPTAL'`).first();return c.json({ok:true,planned,by_publisher:byPublisher.results,by_grade:byGrade.results,losses:losses.results,operations:applied})});

// USERS / SEASONS
app.get('/api/users', requireRoles('SUPER_ADMIN','ADMIN'), async c=>{const r=await c.env.DB.prepare(`SELECT id,email,login_code,full_name,role,status,institution_id,must_change_password,created_at FROM users WHERE deleted_at IS NULL ORDER BY CASE role WHEN 'SUPER_ADMIN' THEN 0 ELSE 1 END,full_name`).all();return c.json({ok:true,items:r.results})});
app.post('/api/users', requireRoles('SUPER_ADMIN','ADMIN'), async c=>{const b:any=await c.req.json();if(!b.full_name||!b.email||!b.password||!b.role)return fail(c,'Ad soyad, e-posta, şifre ve rol gerekli.');if(b.role==='SUPER_ADMIN')return fail(c,'Yeni Süper Admin oluşturulamaz.',403);if(String(b.password).length<8)return fail(c,'Geçici şifre en az 8 karakter olmalı.');const rid=uid('user');await c.env.DB.prepare(`INSERT INTO users(id,email,password_hash,full_name,role,status,institution_id,must_change_password,login_code,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)`).bind(rid,String(b.email).trim().toLowerCase(),await hashPassword(String(b.password)),b.full_name,b.role,b.status||'ACTIVE',b.institution_id||null,1,b.login_code?normalizeCode(b.login_code):null,now(),now()).run();await audit(c.env.DB,c.get('user'),'CREATE','user',rid,undefined,{...b,password:'***'});return c.json({ok:true,id:rid},201)});
app.patch('/api/users/:id', requireRoles('SUPER_ADMIN','ADMIN'), async c=>{const actor=c.get('user'),rid=c.req.param('id'),b:any=await c.req.json();const row=await c.env.DB.prepare(`SELECT * FROM users WHERE id=? AND deleted_at IS NULL`).bind(rid).first<any>();if(!row)return fail(c,'Kullanıcı bulunamadı.',404);if(row.role==='SUPER_ADMIN'){if(actor.role!=='SUPER_ADMIN'||actor.id!==row.id)return fail(c,'Süper Admin hesabı dokunulmazdır.',403);const keys=Object.keys(b).filter(k=>b[k]!==undefined);if(!b.password||keys.some(k=>k!=='password'))return fail(c,'Süper Admin hesabında yalnız şifre değiştirilebilir.',403);if(String(b.password).length<10)return fail(c,'Süper Admin şifresi en az 10 karakter olmalı.');await c.env.DB.prepare(`UPDATE users SET password_hash=?,must_change_password=0,updated_at=? WHERE id=?`).bind(await hashPassword(String(b.password)),now(),rid).run();await c.env.DB.prepare(`DELETE FROM sessions WHERE user_id=? AND id NOT IN (SELECT id FROM sessions WHERE user_id=? ORDER BY created_at DESC LIMIT 1)`).bind(rid,rid).run();await audit(c.env.DB,actor,'PASSWORD_CHANGE','user',rid);return c.json({ok:true,protected:true})}if(b.role==='SUPER_ADMIN')return fail(c,'Bir kullanıcı Süper Admin yapılamaz.',403);if(actor.id===row.id&&b.status==='PASSIVE')return fail(c,'Kendi hesabınızı pasife alamazsınız.',400);await c.env.DB.prepare(`UPDATE users SET full_name=?,email=?,role=?,status=?,institution_id=?,login_code=?,updated_at=? WHERE id=?`).bind(b.full_name??row.full_name,b.email===undefined?row.email:String(b.email).trim().toLowerCase(),b.role??row.role,b.status??row.status,b.institution_id===undefined?row.institution_id:b.institution_id,b.login_code===undefined?row.login_code:normalizeCode(b.login_code),now(),rid).run();if(b.password){if(String(b.password).length<8)return fail(c,'Şifre en az 8 karakter olmalı.');await c.env.DB.prepare(`UPDATE users SET password_hash=?,must_change_password=1,updated_at=? WHERE id=?`).bind(await hashPassword(String(b.password)),now(),rid).run();await c.env.DB.prepare(`DELETE FROM sessions WHERE user_id=?`).bind(rid).run()}await audit(c.env.DB,actor,'UPDATE','user',rid,row,{...b,password:b.password?'***':undefined});return c.json({ok:true})});
app.delete('/api/users/:id', requireRoles('SUPER_ADMIN','ADMIN'), async c=>{const actor=c.get('user'),rid=c.req.param('id');const row=await c.env.DB.prepare(`SELECT * FROM users WHERE id=? AND deleted_at IS NULL`).bind(rid).first<any>();if(!row)return fail(c,'Kullanıcı bulunamadı.',404);if(row.role==='SUPER_ADMIN')return fail(c,'Süper Admin hesabı silinemez.',403);if(actor.id===row.id)return fail(c,'Kendi hesabınızı silemezsiniz.',400);await c.env.DB.prepare(`UPDATE users SET status='PASSIVE',deleted_at=?,updated_at=? WHERE id=?`).bind(now(),now(),rid).run();await c.env.DB.prepare(`DELETE FROM sessions WHERE user_id=?`).bind(rid).run();await audit(c.env.DB,actor,'DELETE','user',rid,row,undefined);return c.json({ok:true})});
app.get('/api/seasons', async c=>{const r=await c.env.DB.prepare(`SELECT * FROM seasons ORDER BY year_start DESC`).all();return c.json({ok:true,items:r.results})});
app.post('/api/seasons', requireRoles('SUPER_ADMIN','ADMIN'), async c=>{const b:any=await c.req.json();if(!b.name||!b.year_start||!b.year_end)return fail(c,'Sezon bilgileri gerekli.');if(Number(b.year_end)<=Number(b.year_start))return fail(c,'Bitiş yılı başlangıç yılından büyük olmalı.');if(b.is_active)await c.env.DB.prepare(`UPDATE seasons SET is_active=0`).run();const rid=uid('season');await c.env.DB.prepare(`INSERT INTO seasons(id,name,year_start,year_end,is_active,created_at,updated_at) VALUES(?,?,?,?,?,?,?)`).bind(rid,b.name,Number(b.year_start),Number(b.year_end),b.is_active?1:0,now(),now()).run();await audit(c.env.DB,c.get('user'),'CREATE','season',rid,undefined,b);return c.json({ok:true,id:rid},201)});
app.patch('/api/seasons/:id', requireRoles('SUPER_ADMIN','ADMIN'), async c=>{const rid=c.req.param('id'),b:any=await c.req.json();const row=await c.env.DB.prepare(`SELECT * FROM seasons WHERE id=?`).bind(rid).first<any>();if(!row)return fail(c,'Sezon bulunamadı.',404);const ys=Number(b.year_start??row.year_start),ye=Number(b.year_end??row.year_end);if(ye<=ys)return fail(c,'Bitiş yılı başlangıç yılından büyük olmalı.');if(b.is_active===true)await c.env.DB.prepare(`UPDATE seasons SET is_active=0 WHERE id<>?`).bind(rid).run();await c.env.DB.prepare(`UPDATE seasons SET name=?,year_start=?,year_end=?,is_active=?,updated_at=? WHERE id=?`).bind(b.name??row.name,ys,ye,b.is_active===undefined?row.is_active:(b.is_active?1:0),now(),rid).run();await audit(c.env.DB,c.get('user'),'UPDATE','season',rid,row,b);return c.json({ok:true})});

export default app;
